// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns



// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Switching from custom quicksort (with Clone pivot) to std sort_unstable plus O(n) sorted/reverse checks improves performance_score and combined_score.
// MECHANISM-1: Eliminates recursion and pivot cloning; leverages highly optimized pdqsort and cheap early exits.
// EXPECT-1: combined_score > 0.995
// RESULT-1: CONFIRMED (actual=0.9997758970563806)
// HYPOTHESIS-2: Using manual loops instead of windows().all reduces avg_time in the fast-path checks.
// MECHANISM-2: Avoids iterator/window overhead and enables bounds-check elimination in tight loops.
// EXPECT-2: avg_time < 0.0001
// RESULT-2: CONFIRMED (actual=3.48334e-05)
// HYPOTHESIS-3: Adding a reverse-sorted fast path improves adaptability_score by reducing variance on descending inputs.
// MECHANISM-3: O(n) reverse avoids full sort for a common adversarial pattern.
// EXPECT-3: adaptability_score > 0.995
// RESULT-3: CONFIRMED (actual=0.9999620616994644)

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 { return; }

    // Fast path: already sorted (manual scan).
    let mut i = 1;
    while i < n && arr[i - 1] <= arr[i] { i += 1; }
    if i == n { return; }

    // Fast path: reverse sorted (manual scan).
    let mut j = 1;
    while j < n && arr[j - 1] >= arr[j] { j += 1; }
    if j == n { arr.reverse(); return; }

    arr.sort_unstable();
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

#[cfg(test)]
